package com.vms.vendorcontractmanagement.controller; import com.vms.vendorcontractmanagement.dto.ContractDtos.*; import com.vms.vendorcontractmanagement.service.*; import jakarta.validation.*; import lombok.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/contracts") @RequiredArgsConstructor public class ContractController {final ContractService service;@GetMapping public Page<Response> list(@RequestParam(required=false) String search,@RequestParam(required=false) String status,Pageable pageable){return service.list(search,status,pageable);}@GetMapping("/expiring") public List<Response> expiring(@RequestParam(defaultValue="30") int days){return service.expiring(days);}@GetMapping("/{id}") public Response get(@PathVariable Long id){return service.get(id);}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") @ResponseStatus(HttpStatus.CREATED) public Response create(@Valid @RequestBody Request r){return service.create(r);}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") public Response update(@PathVariable Long id,@Valid @RequestBody Request r){return service.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
